const decisions=['ขอข้อมูลเพิ่ม','เตรียม notice','เสนอให้ฟ้อง','เสนอไม่ฟ้อง'];
let state,view=views[Number(new URLSearchParams(location.search).get('variant')||1)-1]||'work',tab='mail',toastTimer;
function initial(){return {reviewMode:false,acting:'',decision:'ขอข้อมูลเพิ่ม',reason:'ยังขาดหลักฐานการส่งมอบที่ลงนามรับ จึงต้องขอเพิ่มก่อนยืนยันแนวทางดำเนินการ',assessed:false,template:'แบบสำนักงาน',version:1,prepared:false,reviewers:[],editors:[names[0]],approved:[],reviewStatus:'draft',reviewNote:'ตรวจเหตุผลในร่างคำตอบและความครบถ้วนของเอกสารประกอบ',returnReason:'',deadline:'2026-09-10',replyReady:false,activities:['09:12 · รับเมลและจัดไฟล์แนบเข้าเรื่องเดียวกัน (ตัวอย่าง)'],formError:''}}
state=initial();
function log(s){state.activities.unshift(s)}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800)}
function setView(v){view=v;const u=new URL(location.href);u.searchParams.set('variant',String(views.indexOf(v)+1));history.replaceState(null,'',u);render()}
function go(t){state.reviewMode=false;tab=t;setView('work')}
function badge(){return state.reviewStatus==='approved'?'<span class="tag green">ผ่านตรวจ · v'+state.version+'</span>':state.reviewStatus==='review'?'<span class="tag amber">รอตรวจ · v'+state.version+'</span>':state.reviewStatus==='changes'?'<span class="tag amber">ส่งกลับให้แก้</span>':'<span class="tag">ร่างภายใน</span>'}
function heading(title,desc,right=''){return `<div class="heading"><div><div class="eyebrow">PRE-LITIGATION / MATTER WORKSPACE</div><h1>${title}</h1><p>${desc}</p></div><div class="row">${right}</div></div>`}
function panel(title,body,extra=''){return `<section class="panel"><div class="panelhead"><h3>${title}</h3>${extra}</div><div class="panelbody">${body}</div></section>`}
function side(){return `<aside class="side">${panel('เรื่องนี้ใครดูแล',`<div class="row"><span class="avatar">น</span><div><b style="font-size:13px">${names[0]}</b><small style="display:block">ผู้รับผิดชอบเรื่อง</small></div></div><dl class="facts"><div><dt>สถานะเรื่อง</dt><dd>${state.assessed?'ประเมินแล้ว':'รอทนายประเมิน'}</dd></div><div><dt>แนวทาง</dt><dd>${state.assessed?state.decision:'ยังไม่ยืนยัน'}</dd></div><div><dt>ผู้ตรวจรอบนี้</dt><dd>${state.reviewers.length?state.reviewers.map(escapeHtml).join('<br>'):'ยังไม่ส่งตรวจ'}</dd></div><div><dt>ผู้แก้เอกสาร</dt><dd>${state.editors.map(escapeHtml).join('<br>')}</dd></div></dl>`)}${panel('เตรียมให้แล้ว',`<div class="statusline"><span class="closed">✓</span> รวมเมลและไฟล์แนบ 3 ไฟล์</div><div class="statusline"><span class="closed">✓</span> จับคู่ลูกค้าเข้ากับเรื่อง</div><div class="statusline"><span class="closed">✓</span> เตรียมสรุปพร้อมแหล่งอ้างอิง</div><div class="statusline"><span class="closed">✓</span> เตรียมชื่อไฟล์และที่เก็บ</div><p class="caption">สถานะตัวอย่าง · ${state.assessed?'แนวทางยืนยันโดยทนายแล้ว':'ผลสรุปยังรอทนายยืนยัน'}</p>`)}${panel('ประวัติในเรื่องเดียว',`<div class="activitybox">${state.activities.map(s=>`<div class="activity">${escapeHtml(s)}</div>`).join('')}</div>`)}<p class="caption">เอกสารและการอนุมัติอยู่ภายในสำนักงาน<br>ลูกค้ายังไม่เห็นร่างหรือความเห็นภายใน</p></aside>`}
function renderWork(){const ts=[['mail','รับเรื่อง'],['assess','ประเมิน'],['docs','เตรียม Word'],['review','ตรวจ / แก้'],['reply','ตอบลูกค้า']];return heading('พิจารณาเรียกชำระค่าสินค้า','บริษัท รุ่งเรือง เทรดดิ้ง · IN-2026-014 · รับจากอีเมลวันนี้ 09:12',`<span class="tag amber">ก่อนฟ้อง</span>${badge()}`)+`<div class="steps">${ts.map(([k,n],i)=>`<button class="${tab===k?'active':''}" data-tab="${k}"><em>${i+1}</em>${n}</button>`).join('')}</div><div class="workspace"><div>${({mail:mailPane,assess:assessPane,docs:docsPane,review:reviewPane,reply:replyPane})[tab]()}</div>${side()}</div>`}
function mailPane(){return `<section class="panel"><div class="panelhead"><h3>อีเมลจากลูกค้า</h3><span class="tag">รวมเข้าเรื่องแล้ว</span></div><div class="panelbody"><h2>ขอปรึกษาเรื่องลูกค้าค้างชำระค่าสินค้า</h2><div class="mailmeta"><span class="avatar">ร</span><div><strong>ฝ่ายบัญชี · รุ่งเรือง เทรดดิ้ง</strong><small style="display:block">ถึง: ทีมกฎหมาย · วันนี้ 09:12 · ข้อมูลสมมติ</small></div></div><div class="mailbody">เรียนทีมทนาย<br>บริษัทคู่ค้ายังค้างชำระค่าสินค้าตามเอกสารแนบ รบกวนช่วยพิจารณาว่าควรดำเนินการอย่างไร และมีเอกสารอะไรที่ต้องเตรียมเพิ่มเติมบ้างค่ะ<br><br>แนบสัญญาซื้อขาย ใบแจ้งหนี้ และอีเมลติดตามมาให้ตรวจสอบค่ะ</div><div class="files">${[['PDF','สัญญาซื้อขาย.pdf','12 หน้า'],['PDF','ใบแจ้งหนี้.pdf','2 หน้า'],['EML','อีเมลติดตาม.eml','บทสนทนา 3 ฉบับ']].map(([a,b,c],i)=>`<button class="file" data-source="${i}"><span>${a}</span>${b}<small>${c}</small></button>`).join('')}</div></div><div class="prepared"><div><b>พร้อมเริ่มพิจารณา โดยไม่ต้องกรอกเรื่องซ้ำ</b><span>สรุปข้อมูลและจุดที่ขาดไว้ให้แล้ว · ทนายตรวจยืนยันก่อนใช้</span></div><button class="primary" data-tab="assess">เปิดสรุปเรื่อง →</button></div></section><div class="nextbar"><small>เมลติดตามจะเสนอให้รวมกับเรื่องเดิม หากจับคู่ไม่แน่ใจต้องให้คนยืนยัน</small><button data-action="match">ดูการจับคู่เรื่อง</button></div>`}
function assessPane(){return panel('สรุปสำหรับทนายพิจารณา',`<div class="notice">ข้อมูลตัวอย่างเพื่อออกแบบหน้าจอ · ยังไม่ใช่ความเห็นกฎหมายหรือข้อสรุปว่าควรฟ้อง</div><div class="summaryline"><h4>01 · ประเด็นที่ลูกค้าต้องการคำตอบ</h4><p class="muted">ควรดำเนินการอย่างไรกับยอดค้าง และต้องขอเอกสารใดเพิ่มเติม</p><button class="source" data-source="2">อีเมลลูกค้า · ดูต้นทาง ↗</button></div><div class="summaryline"><h4>02 · เอกสารที่มีอยู่</h4><p class="muted">สัญญาซื้อขาย ใบแจ้งหนี้ และประวัติติดตาม ยังต้องตรวจความสอดคล้องระหว่างฉบับ</p><button class="source" data-source="0">สัญญาซื้อขาย · ดูต้นทาง ↗</button></div><div class="summaryline"><h4>03 · จุดที่ยังต้องยืนยัน</h4><p class="muted">หลักฐานส่งมอบและการรับสินค้า ยอดที่ชำระมาแล้ว และข้อโต้แย้งจากคู่ค้า</p><span class="tag amber">รอข้อมูลเพิ่มเติม</span></div><label>ทนายเลือกแนวทาง</label><div class="decision">${decisions.map((d,i)=>`<button data-decision="${i}" class="${state.decision===d?'chosen':''}">${state.decision===d?'●':'○'} ${d}</button>`).join('')}</div><label for="reason">เหตุผล / สิ่งที่ต้องดำเนินการต่อ</label><textarea id="reason">${escapeHtml(state.reason)}</textarea><p class="caption">ใช้ข้อความที่ยืนยันนี้ประกอบร่างคำตอบลูกค้า ไม่เปลี่ยนข้อเสนอของ AI เป็นข้อสรุปเอง</p><div class="nextbar"><small>${state.assessed?'ยืนยันแนวทางแล้ว · เปลี่ยนได้โดยทบทวนร่างเดิม':'บันทึกครั้งเดียว ใช้ต่อในร่าง Word และร่างเมล'}</small><button class="primary" data-action="confirm-assessment">ยืนยันและเตรียมร่าง →</button></div>`,state.assessed?'<span class="tag green">ยืนยันแล้ว</span>':'<span class="tag amber">รอพิจารณา</span>')}
function documentTitle(){return state.decision==='เตรียม notice'?'หนังสือบอกกล่าว — ร่างภายใน':state.decision==='เสนอให้ฟ้อง'?'ความเห็นแนวทางดำเนินคดี':state.decision==='เสนอไม่ฟ้อง'?'ความเห็นและแนวทางอื่น':'หนังสือขอเอกสารเพิ่มเติม'}
function reviewDocument(){
 const mine=state.approved.includes(state.acting), allowed=state.reviewStatus==='review'&&state.reviewers.includes(state.acting)&&!mine;
 const result=state.reviewStatus==='approved'?'ผ่านการตรวจครบทุกคนแล้ว':mine?'คุณตรวจผ่านแล้ว · ยังรอผู้ตรวจคนอื่น':state.reviewStatus==='changes'?'ส่งกลับให้แก้ไขแล้ว':state.reviewStatus==='draft'?'มีฉบับแก้ไขใหม่ · รอส่งตรวจอีกครั้ง':'อ่านเอกสารแล้วเลือกผลการตรวจด้านล่าง';
 return panel('ตรวจเอกสาร · v'+state.version,`<div class="documentbar"><div><b>กำลังตรวจในนาม ${escapeHtml(state.acting)}</b><small style="display:block">${escapeHtml(state.reviewNote)}</small></div><button data-view="review">กลับคิวตรวจ</button></div><div class="paper"><div class="eyebrow">IN-2026-014 · V${state.version}</div><h3>${documentTitle()}</h3><p>เรียน บริษัท รุ่งเรือง เทรดดิ้ง</p><p>ตามที่ท่านส่งเอกสารประกอบการพิจารณาเรื่องการเรียกชำระค่าสินค้า</p><p>${escapeHtml(state.reason)}</p><p class="muted">[เนื้อหาตัวอย่าง — ฉบับสำหรับตรวจภายใน]</p><p>สำนักงานตัวอย่าง</p></div><div class="review-decision"><div><b>${result}</b><small style="display:block">ผลตรวจผูกกับ v${state.version} · ไม่ใช่การส่งเอกสารให้ลูกค้า</small></div><div class="row"><button data-action="return" ${allowed?'':'disabled'}>ส่งกลับแก้ไข</button><button class="primary" data-action="approve" ${allowed?'':'disabled'}>${mine?'✓ คุณตรวจผ่านแล้ว':'ผ่านการตรวจ'}</button></div></div>`,badge());
}
function docsPane(){if(state.reviewMode)return reviewDocument();return panel('เตรียมเอกสารจากข้อมูลเรื่อง',`<div class="documentbar"><div><b>${documentTitle()}</b><small style="display:block">OneDrive / รุ่งเรือง / IN-2026-014 / ร่างเอกสาร · ตัวอย่างตำแหน่งจัดเก็บ</small></div>${badge()}</div><div class="doclayout"><div class="paper"><div class="eyebrow">DRAFT · IN-2026-014 · V${state.version}</div><h3>${documentTitle()}</h3><p>เรียน <mark>บริษัท รุ่งเรือง เทรดดิ้ง</mark></p><p>ตามที่ท่านได้ส่งเอกสารประกอบการพิจารณาเรื่องการเรียกชำระค่าสินค้าให้สำนักงานนั้น</p><p>${escapeHtml(state.reason)}</p><p>จึงเรียนมาเพื่อโปรดพิจารณาและแจ้งข้อมูลประกอบเพิ่มเติมตามที่ระบุ</p><p class="muted">[เนื้อหาตัวอย่าง — ทนายแก้ไขและยืนยันก่อนใช้]</p><p style="text-align:right">สำนักงานตัวอย่าง<br>ผู้รับผิดชอบเรื่อง</p></div><div><h4>เลือกต้นแบบ</h4><div class="doclist sectiongap">${['แบบสำนักงาน','ไฟล์คดีเก่า','แบบฟอร์มศาล'].map(x=>`<button data-template="${x}" class="${state.template===x?'primary':''}">${x}</button>`).join('')}</div><div class="sectiongap"><span class="tag green">เติมข้อมูลเรื่องแล้ว</span><p class="caption">ชื่อบริษัท · เลขรับเรื่อง · แนวทางที่ทนายยืนยัน</p></div><div class="notice sectiongap">${state.template==='ไฟล์คดีเก่า'?'ต้องตรวจชื่อคู่ความ วันที่ และข้อเท็จจริงเก่าที่อาจตกค้าง':state.template==='แบบฟอร์มศาล'?'ตัวอย่างนี้ยังไม่มีแบบศาลที่ผ่านการตรวจ จึงยังเตรียมอัตโนมัติไม่ได้':'แบบสำนักงาน · รุ่น 03<br>ตัวอย่างสถานะ: สำนักงานตรวจแล้ว'}</div><button class="text" data-action="template-info">ดูรายละเอียดต้นแบบ ↗</button></div></div><div class="nextbar"><small>${state.assessed?'เปิดแก้ใน Word ตามเดิม แล้วกลับมาส่งตรวจ':'ต้องยืนยันแนวทางในขั้นประเมินก่อนเตรียมไฟล์'}</small><div class="row"><button data-action="edit" ${!state.assessed?'disabled':''}>ลองแก้เนื้อหา</button><button class="primary" data-action="prepare" ${!state.assessed||state.template==='แบบฟอร์มศาล'?'disabled':''}>${state.prepared?'เลือกผู้ตรวจ →':'เตรียม Word →'}</button></div></div><p class="caption">ต้นแบบนี้จำลองไฟล์และการแก้ไขเท่านั้น ยังไม่สร้าง .docx หรือบันทึกลง OneDrive จริง</p>`)}
function reviewPane(){return panel('รอบตรวจเอกสาร',`<div class="documentbar"><div><b>${documentTitle()}</b><small style="display:block">v${state.version} · ${state.prepared?'เตรียมฉบับร่างแล้ว':'ยังไม่ได้เตรียมฉบับร่าง'}</small></div>${badge()}</div>${state.reviewStatus==='changes'?`<div class="notice"><b>ข้อแก้ไขจากผู้ตรวจ</b><br>${escapeHtml(state.returnReason)}</div>`:''}${state.reviewStatus==='approved'?'<div class="approved"><b>ผู้ตรวจที่เลือกยืนยันครบแล้ว</b><br>การอนุมัติผูกกับฉบับนี้ หากแก้เนื้อหาจะต้องตรวจฉบับใหม่</div>':''}<div class="split"><div><h4>ผู้แก้เอกสาร</h4><p class="muted">${state.editors.map(escapeHtml).join(' · ')}</p><button class="text" data-action="assign">เปลี่ยนผู้แก้ / ผู้ตรวจ</button></div><div><h4>ผู้ตรวจรอบนี้</h4>${state.reviewers.length?state.reviewers.map(n=>`<p class="muted">${escapeHtml(n)} ${state.approved.includes(n)?'✓ ยืนยันแล้ว':'· รอตรวจ'}</p>`).join(''):'<p class="muted">เลือกได้จากคนที่มีสิทธิ์ในเรื่อง</p>'}</div></div><div class="summaryline"><h4>ขอบเขตการตรวจ</h4><p class="muted">${escapeHtml(state.reviewNote)}</p><small>กำหนดตรวจ: ${state.reviewers.length?escapeHtml(state.deadline):'ยังไม่ระบุ'} · ผู้ตรวจทุกคนที่เลือกต้องยืนยัน</small></div><div class="row sectiongap"><button data-action="paper" ${!state.prepared?'disabled':''}>ตรวจบนกระดาษ</button><button data-action="edit" ${!state.prepared?'disabled':''}>ลองแก้เป็นรุ่นใหม่</button><button class="primary" data-action="assign" ${!state.prepared?'disabled':''}>${state.reviewStatus==='changes'?'ส่งตรวจอีกครั้ง':'ส่ง / ปรับรอบตรวจ'}</button></div>${state.reviewStatus==='review'?`<div class="sectiongap notice">ลองสวมบทบาทผู้ตรวจในหน้าคิวเอกสาร เพื่อรับงาน ส่งกลับแก้ หรือยืนยันฉบับนี้</div><button class="primary" data-view="review">เปิดคิวผู้ตรวจ →</button>`:''}${state.reviewStatus==='approved'?'<div class="nextbar"><small>ฉบับผ่านตรวจพร้อมใช้ประกอบร่างคำตอบ</small><button class="primary" data-tab="reply">เตรียมคำตอบลูกค้า →</button></div>':''}<p class="caption">การเปลี่ยนผู้ทำงานเลือกได้เฉพาะคนที่เข้าถึงเรื่องแล้ว ไม่เพิ่มสิทธิ์ข้อมูลให้ทั้งสำนักงานอัตโนมัติ</p>`)}
function replyPane(){return panel('ร่างคำตอบลูกค้า',`<div class="row"><span class="tag">อีเมลร่าง</span><span class="tag amber">ยังไม่ส่ง</span></div><dl class="facts"><div><dt>ถึง</dt><dd>ผู้ส่งเมลต้นเรื่อง · บริษัท รุ่งเรือง</dd></div><div><dt>หัวข้อ</dt><dd>Re: ขอปรึกษาเรื่องค้างชำระค่าสินค้า</dd></div></dl><div class="paper sectiongap"><p>เรียน ทีมงานบริษัท รุ่งเรือง เทรดดิ้ง</p><p>สำนักงานได้พิจารณาข้อมูลเบื้องต้นตามเอกสารที่ได้รับแล้ว โดยมีแนวทางดังนี้</p><p><b>${state.assessed?state.decision:'[รอทนายยืนยันแนวทาง]'}</b></p><p>${escapeHtml(state.reason)}</p><p>ทั้งนี้ หากมีข้อมูลหรือเอกสารเพิ่มเติม กรุณาส่งกลับในอีเมลชุดนี้เพื่อประกอบการพิจารณา</p><p>ขอแสดงความนับถือ<br>สำนักงานตัวอย่าง</p></div><div class="checkrow"><input id="replycheck" type="checkbox" ${state.replyReady?'checked':''}><label for="replycheck">ตรวจผู้รับ เหตุผล และฉบับเอกสารแล้ว</label></div>${state.reviewStatus!=='approved'?'<div class="notice sectiongap">รอเอกสารฉบับปัจจุบันผ่านตรวจ จึงจะเตรียมร่างใน Outlook ได้</div>':''}<div class="nextbar"><small>สร้างร่างกับส่งอีเมลเป็นคนละขั้นตอน ผู้ใช้ตรวจใน Outlook ก่อนส่ง</small><button class="primary" data-action="outlook" ${state.reviewStatus!=='approved'?'disabled':''}>เตรียมร่างใน Outlook</button></div>${state.decision==='เสนอให้ฟ้อง'?'<div class="approved">หลังยืนยันการรับงาน จึงเปิดคดีโดยใช้ข้อมูลและเอกสารจากเรื่องนี้ต่อ ไม่ต้องกรอกใหม่</div>':state.decision==='เตรียม notice'?'<div class="approved">หลังส่ง notice ต้องบันทึกการส่งจริงและกำหนดติดตาม แล้วกลับมาประเมินผลอีกครั้ง</div>':state.decision==='เสนอไม่ฟ้อง'?'<div class="approved">ปิดเรื่องเป็น “ให้คำปรึกษาแล้ว” ได้หลังส่งคำตอบจริง โดยเก็บเหตุผลและฉบับผ่านตรวจไว้</div>':''}`)}
function renderReview(){let pending=state.reviewers.filter(n=>!state.approved.includes(n));return heading('ตรวจงานโดยไม่ต้องตามหาไฟล์','เลือกใครตรวจหรือใครแก้ก็ได้ จากทีมที่เข้าถึงเรื่องนี้อยู่แล้ว',`<button data-view="work">กลับไปที่เรื่อง ↗</button>`)+`<div class="reviewhero">${panel('คิวของฉัน',`<div class="row"><span class="avatar">ต</span><div><b>ลองสวมบทบาทผู้ตรวจ</b><small style="display:block">ตัวอย่างเท่านั้น ไม่เปลี่ยนบัญชีจริง</small></div></div><label for="acting">กำลังตรวจในนาม</label><select id="acting">${(state.reviewers.length?state.reviewers:names.slice(1)).map(n=>`<option ${state.acting===n?'selected':''}>${escapeHtml(n)}</option>`).join('')}</select>`)}${panel('งานต้องเดินต่อได้',`<p>ผู้ร่าง ผู้แก้ และผู้ตรวจเปลี่ยนตามเอกสารได้ ทุกครั้งเก็บว่าใครตรวจรุ่นไหน และยังรอใครอยู่</p><div class="row">${badge()}<span class="tag">${state.reviewStatus==='review'?pending.length:0} คนรอยืนยัน</span></div>`)}</div><section class="panel"><div class="panelhead"><h3>เอกสารในรอบตรวจ</h3><small>ตัวอย่าง 1 เรื่อง</small></div>${!state.reviewers.length?'<div class="empty">ยังไม่มีงานส่งตรวจ<br>เริ่มจากประเมินเรื่องและเตรียม Word ก่อน<div class="sectiongap"><button class="primary" data-action="start-review">เปิดเรื่องตัวอย่าง →</button></div></div>':`<table class="queue"><thead><tr><th>เอกสาร / เรื่อง</th><th>ฉบับและสถานะ</th><th>ผู้แก้</th><th>ดำเนินการ</th></tr></thead><tbody><tr><td><b>${documentTitle()}</b><small>รุ่งเรือง เทรดดิ้ง · IN-2026-014</small></td><td>${badge()}<small>ทุกคนที่เลือกต้องยืนยัน</small></td><td>${state.editors.map(escapeHtml).join('<br>')}</td><td><div class="actions"><button data-action="review-detail">เปิดตรวจ</button><button data-action="return" ${state.reviewStatus!=='review'?'disabled':''}>ส่งกลับแก้</button><button class="primary" data-action="approve" ${state.reviewStatus!=='review'?'disabled':''}>ยืนยันฉบับนี้</button></div></td></tr></tbody></table>`}</section><div class="split sectiongap">${panel('ส่งกลับแล้วไม่สูญบริบท',`<p class="muted">แนบคำอธิบายข้อแก้ไขกับรุ่นเอกสาร ผู้แก้เห็นในเรื่องเดิม และส่งฉบับใหม่กลับเข้าคิวได้</p><p class="caption">${state.returnReason?escapeHtml(state.returnReason):'รองรับทั้งความเห็นในไฟล์ และการคืนกระดาษขีดแก้'}</p>`)}${panel('ยืนยันแล้วไม่ส่งเอง',`<p class="muted">ผ่านตรวจหมายถึงอนุมัติรุ่นเอกสารนั้น ยังไม่ใช่การส่งอีเมล ส่ง notice หรือยื่นฟ้อง</p><p class="caption">หากเนื้อหาหรือแนวทางเปลี่ยน ต้องทบทวนฉบับใหม่</p>`)}</div>`}
function renderFlow(){const cards=[['รับเมล → รวมเรื่อง','เก็บอีเมล ไฟล์แนบ และลูกค้าในเรื่องเดียว',['ระบบเสนอจับคู่เมลติดตาม','คนยืนยันเมื่อมีหลายเรื่องที่อาจตรงกัน'],'mail'],['ประเมิน → เลือกแนวทาง','สรุปข้อเท็จจริงและสิ่งที่ขาด พร้อมย้อนดูต้นทาง',['ทนายยืนยันเหตุผลเอง','ยังไม่ฟ้องก็เก็บเป็นเรื่องได้'],'assess'],['เตรียม Word → แก้ต่อ','เลือกแบบสำนักงาน ไฟล์เก่า หรือแบบศาล',['เติมข้อมูลที่ยืนยันแล้ว','คงไฟล์ใน OneDrive ของสำนักงาน'],'docs'],['เลือกทีม → ส่งตรวจ','เลือกผู้ตรวจและผู้แก้ตามงาน ไม่ล็อกตำแหน่ง',['ตรวจใน Word หรือกระดาษ','ส่งกลับพร้อมเหตุผล → แก้ → ส่งใหม่'],'review'],['ผ่านตรวจ → เตรียมคำตอบ','ผูกการยืนยันกับรุ่นเอกสารและผู้ตรวจ',['ตรวจผู้รับและเอกสารแนบ','สร้างอีเมลร่าง ยังไม่ส่งอัตโนมัติ'],'reply'],['ดำเนินการ → ติดตามผล','ยืนยันการส่งจริงแล้วจึงเดินขั้นต่อไป',['notice → ติดตาม → ประเมินใหม่','รับงานฟ้อง → เปิดคดีโดยใช้ข้อมูลเดิม'],'reply']];return heading('จากเมลหนึ่งฉบับ สู่งานที่พร้อมทำต่อ','ระบบเตรียมและตามสถานะให้ · ทนายพิจารณา ตรวจ และยืนยัน',`<button class="primary" data-tab="mail">ลองตั้งแต่ต้น →</button>`)+`<div class="flowgrid">${cards.map(([title,desc,items,t],i)=>`<article class="flowcard"><span class="number">0${i+1}</span><h3>${title}</h3><p>${desc}</p><ul>${items.map(x=>`<li>${x}</li>`).join('')}</ul><button data-tab="${t}">ดูหน้าจอขั้นนี้ →</button></article>`).join('')}</div><section class="sectiongap"><h3>ประเมินแล้วไปได้หลายทาง</h3><div class="branch"><div><b>ขอข้อมูลเพิ่ม</b><small>เตรียมคำขอ → ลูกค้าตอบ → ประเมินต่อ</small></div><div><b>ส่ง notice</b><small>ร่าง → ตรวจ → ส่งจริง → ติดตามผล</small></div><div><b>ควรฟ้อง</b><small>ความเห็น → ตรวจ → ยืนยันรับงาน → เปิดคดี</small></div><div><b>ไม่ควรฟ้อง</b><small>เหตุผล / ทางเลือก → ตรวจ → ตอบ → ปิดเรื่อง</small></div></div></section><div class="notice sectiongap">ไม่มีขั้นไหนส่งออกให้ลูกค้าเพียงเพราะ AI สรุปเสร็จ และการเลือกผู้ตรวจไม่เพิ่มสิทธิ์เข้าถึงเรื่องโดยอัตโนมัติ</div>`}
document.addEventListener('change',e=>{if(e.target.id==='acting')state.acting=e.target.value});
function render(){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('selected',b.dataset.view===view));$('#main').innerHTML=view==='review'?renderReview():view==='flow'?renderFlow():renderWork();$('#reviewCount').textContent=state.reviewStatus==='review'?'1':'0';$('#variantName').textContent=viewNames[views.indexOf(view)];}
function modal(title,body,footer=''){ $('#modalContent').innerHTML=`<div class="modalhead"><h3>${title}</h3><button data-action="close" aria-label="ปิดหน้าต่าง">✕</button></div><div class="modalbody">${body}</div>${footer?`<div class="modalfoot">${footer}</div>`:''}`;if(!$('#modal').open)$('#modal').showModal() }
function assignModal(){if(!state.prepared){toast('เตรียมฉบับ Word ก่อนส่งตรวจ');return}modal('ส่งฉบับ v'+state.version+' ให้ทีมตรวจ',`<p class="muted">เลือกได้หลายคนจากผู้ที่เข้าถึงเรื่องนี้แล้ว ตำแหน่งในสำนักงานไม่กำหนดว่าใครต้องตรวจ</p><label>ผู้ตรวจ · ทุกคนที่เลือกต้องยืนยัน</label><div class="people">${names.map((n,i)=>`<div class="person"><input id="r${i}" name="reviewer" type="checkbox" value="${n}" ${state.reviewers.includes(n)?'checked':''}><label for="r${i}">${n}<small style="display:block">${roles[i]}</small></label></div>`).join('')}</div><label>ผู้แก้เอกสาร</label><div class="people">${names.map((n,i)=>`<div class="person"><input id="e${i}" name="editor" type="checkbox" value="${n}" ${state.editors.includes(n)?'checked':''}><label for="e${i}">${n}</label></div>`).join('')}</div><label for="reviewNote">ต้องการให้ตรวจอะไร</label><textarea id="reviewNote">${escapeHtml(state.reviewNote)}</textarea><label for="due">กำหนดตรวจ</label><input id="due" type="date" value="${state.deadline}"><p id="assignError" class="error" role="alert"></p><p class="caption">ปรับรอบตรวจจะเริ่มการยืนยันใหม่ คนแก้และคนตรวจซ้ำกันได้หากกติกาสำนักงานอนุญาต</p>`,`<button data-action="close">ยกเลิก</button><button class="primary" data-action="submit-review">ส่งเข้าคิวตรวจ</button>`)}
function edited(text){state.reason=text;state.version++;state.approved=[];state.reviewStatus='draft';state.replyReady=false;log('บันทึกฉบับ v'+state.version+' · ยกเลิกผลตรวจฉบับก่อนสำหรับเนื้อหาใหม่');render()}
function action(a){if(a==='close'){$('#modal').close();return}if(a==='reset'){state=initial();tab='mail';setView('work');toast('เริ่มตัวอย่างใหม่แล้ว');return}if(a==='confirm-assessment'){let r=$('#reason').value.trim();if(!r){toast('ระบุเหตุผลหรือข้อมูลที่ต้องขอเพิ่มก่อน');$('#reason').focus();return}if(state.assessed&&state.reason!==r)edited(r);state.reason=r;state.assessed=true;log('ทนายยืนยันแนวทาง: '+state.decision);go('docs');return}if(a==='prepare'){state.prepared=true;log('เตรียมร่าง v'+state.version+' จาก'+state.template+' (จำลอง)');render();assignModal();return}if(a==='assign'){assignModal();return}if(a==='submit-review'){let reviewers=[...document.querySelectorAll('[name=reviewer]:checked')].map(e=>e.value),editors=[...document.querySelectorAll('[name=editor]:checked')].map(e=>e.value);if(!reviewers.length||!editors.length||!$('#due').value){$('#assignError').textContent='เลือกผู้ตรวจอย่างน้อย 1 คน ผู้แก้อย่างน้อย 1 คน และวันกำหนดตรวจ';return}state.reviewers=reviewers;state.editors=editors;state.reviewNote=$('#reviewNote').value;state.deadline=$('#due').value;state.approved=[];state.reviewStatus='review';state.replyReady=false;log('ส่ง v'+state.version+' ให้ '+reviewers.join(', ')+' ตรวจ');$('#modal').close();tab='review';setView('work');toast('งานเข้าคิวผู้ตรวจที่เลือกแล้ว (จำลอง)');return}if(a==='edit'){modal('ลองแก้เนื้อหา Word',`<p class="muted">จำลองการแก้ไฟล์ Word แล้วกลับเข้าระบบ เนื้อหาที่แก้จะเป็นรุ่นใหม่และต้องตรวจใหม่</p><label for="edited">ข้อความในร่าง</label><textarea id="edited">${escapeHtml(state.reason)}</textarea>`,`<button data-action="close">ยกเลิก</button><button class="primary" data-action="save-edit">บันทึกเป็นรุ่นใหม่</button>`);return}if(a==='save-edit'){let r=$('#edited').value.trim();if(!r){toast('กรอกข้อความก่อนบันทึก');return}edited(r);$('#modal').close();toast('สร้าง v'+state.version+' แล้ว · รอส่งตรวจรอบใหม่');return}if(a==='paper'){modal('ตรวจบนกระดาษตามเดิม',`<div class="paper"><div class="eyebrow">ชุดตรวจภายใน · IN-2026-014 · V${state.version}</div><h3>${documentTitle()}</h3><p>ฉบับพิมพ์สำหรับ Senior ขีดแก้และคืนผู้เขียน</p><p>เมื่อรับกระดาษคืน ผู้แก้เปิด Word รุ่นที่ตรงกัน แก้แล้วส่งฉบับใหม่ได้ ไม่บังคับสแกนทุกครั้ง</p></div><p class="caption">แบบศาลต้องตรวจรูปแบบก่อนใช้ รหัสชุดตรวจไม่ควรติดไปบนฉบับยื่นโดยอัตโนมัติ</p>`,`<button data-action="close">ปิด</button><button class="primary" data-action="paper-received">จำลองรับกระดาษคืน</button>`);return}if(a==='paper-received'){state.returnReason='รับกระดาษขีดแก้แล้ว — ตรวจและแก้ตามหมายเหตุในฉบับพิมพ์';state.reviewStatus='changes';state.approved=[];state.replyReady=false;log('ผู้แก้รับกระดาษตรวจคืน · ฉบับ v'+state.version);$('#modal').close();render();return}if(a==='start-review'){go('assess');return}if(a==='review-detail'){state.acting=$('#acting').value;state.reviewMode=true;tab='docs';setView('work');return}if(a==='return'){const acting=$('#acting')?.value||state.acting;modal('ส่งกลับให้แก้',`<p>ผู้ตรวจ: ${escapeHtml(acting)}</p><label for="returnReason">ข้อแก้ไขที่ต้องทำ *</label><textarea id="returnReason" placeholder="ระบุจุดแก้ เพื่อให้ผู้แก้ทำต่อได้ทันที"></textarea><p id="returnError" class="error" role="alert"></p>`,`<button data-action="close">ยกเลิก</button><button class="primary" data-action="submit-return">ส่งข้อแก้ไข</button>`);return}if(a==='submit-return'){const r=$('#returnReason').value.trim();if(!r){$('#returnError').textContent='กรุณาระบุข้อแก้ไขก่อนส่งกลับ';return}state.returnReason=r;state.reviewStatus='changes';state.approved=[];state.replyReady=false;log('ส่ง v'+state.version+' กลับให้แก้: '+r);$('#modal').close();render();return}if(a==='approve'){let n=$('#acting')?.value||state.acting;if(state.reviewStatus!=='review'||!state.reviewers.includes(n)){toast('ฉบับนี้ยังไม่พร้อมให้ผู้ตรวจคนนี้ยืนยัน');return}if(state.approved.includes(n)){toast('ผู้ตรวจคนนี้ยืนยันฉบับนี้แล้ว');return}state.approved.push(n);log(n+' ยืนยัน v'+state.version);if(state.reviewers.every(x=>state.approved.includes(x))){state.reviewStatus='approved';toast('ฉบับนี้ผ่านตรวจครบทุกคนแล้ว')}else toast('บันทึกแล้ว · ยังรอผู้ตรวจอีก '+(state.reviewers.length-state.approved.length)+' คน');render();return}if(a==='outlook'){if(!$('#replycheck').checked){toast('ตรวจผู้รับ เหตุผล และเอกสาร แล้วทำเครื่องหมายยืนยันก่อน');$('#replycheck').focus();return}state.replyReady=true;log('เตรียมร่างคำตอบพร้อมเอกสาร v'+state.version+' · ยังไม่ส่ง');modal('ร่างพร้อมสำหรับตรวจใน Outlook',`<span class="tag green">จำลองเตรียมร่างสำเร็จ</span><h3 class="sectiongap">Re: ขอปรึกษาเรื่องค้างชำระค่าสินค้า</h3><p class="sectiongap">เอกสาร v${state.version} ผ่านตรวจแล้ว ร่างคำตอบและรายการผู้รับพร้อมให้ตรวจครั้งสุดท้าย</p><div class="notice sectiongap">นี่เป็นผลจำลอง ยังไม่มีอีเมลหรือไฟล์ถูกสร้างใน Microsoft 365 และไม่มีการส่งให้ลูกค้า</div>`,`<button class="primary" data-action="close">กลับไปที่เรื่อง</button>`);render();return}if(a==='match'){modal('การจับคู่กับเรื่องเดิม',`<span class="tag">ข้อมูลตัวอย่าง</span><dl class="facts"><div><dt>ลูกค้า</dt><dd>บริษัท รุ่งเรือง เทรดดิ้ง</dd></div><div><dt>อีเมลต้นทาง</dt><dd>บทสนทนาเรื่องค้างชำระ</dd></div><div><dt>เรื่องที่เสนอ</dt><dd>IN-2026-014</dd></div></dl><p class="sectiongap">ถ้าพบหลายเรื่องที่อาจตรงกัน ให้ผู้ใช้เลือกก่อนรวม ไม่จับคู่จากชื่อบริษัทเพียงอย่างเดียว</p>`,`<button class="primary" data-action="close">เข้าใจแล้ว</button>`);return}if(a==='template-info'){modal('ต้นแบบ: '+state.template,`<p>ต้นฉบับทุกแบบเก็บแหล่งที่มา รุ่น วันที่ตรวจ และผู้ตรวจแยกจากเอกสารที่สร้างในคดี</p><div class="notice sectiongap">${state.template==='แบบฟอร์มศาล'?'ยังไม่มีแบบศาลจริงในต้นแบบนี้ ต้องนำแบบที่สำนักงานตรวจแล้วมาตั้งค่าและตรวจฉบับพิมพ์ก่อนเปิดใช้':'ข้อมูลต้นแบบในหน้าจอนี้เป็นตัวอย่าง เมื่อมีรุ่นใหม่ต้องเพิ่มเป็นอีกรุ่น ไม่แทนไฟล์ที่เอกสารเดิมอ้างอิง'}</div>`,`<button class="primary" data-action="close">ปิด</button>`);return}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.view)setView(b.dataset.view);if(b.dataset.tab)go(b.dataset.tab);if(b.dataset.action)action(b.dataset.action);if(b.dataset.decision!==undefined){const reason=$('#reason')?.value;if(reason!==undefined)state.reason=reason;let next=decisions[Number(b.dataset.decision)];if(next!==state.decision){state.decision=next;state.assessed=false;state.prepared=false;state.approved=[];state.reviewStatus='draft';state.replyReady=false;log('เปลี่ยนแนวทาง · ต้องยืนยันและเตรียมร่างใหม่')}render()}if(b.dataset.template){if(state.template!==b.dataset.template){state.template=b.dataset.template;state.prepared=false;state.reviewStatus='draft';state.approved=[];state.replyReady=false;state.version++;log('เปลี่ยนต้นแบบ · ต้องเตรียมและตรวจเอกสารฉบับใหม่')}render()}if(b.dataset.source!==undefined){const i=Number(b.dataset.source);modal(['สัญญาซื้อขาย.pdf','ใบแจ้งหนี้.pdf','อีเมลลูกค้า'][i],`<span class="tag">ต้นทางจำลอง</span><div class="paper sectiongap"><h3>${['สัญญาซื้อขายสินค้า','ใบแจ้งหนี้','อีเมลขอคำปรึกษา'][i]}</h3><p>${['เอกสารแนบที่ลูกค้าส่งเพื่อประกอบการพิจารณา ต้องตรวจคู่สัญญา เงื่อนไข และรายละเอียดกับต้นฉบับจริง','ต้องตรวจยอด วันครบกำหนด และประวัติชำระกับข้อมูลที่ลูกค้ายืนยัน','ลูกค้าขอให้พิจารณาแนวทางดำเนินการและรายการเอกสารที่ต้องเตรียมเพิ่ม'][i]}</p><p class="muted">พื้นที่นี้ในระบบจริงจะแสดงไฟล์ต้นฉบับ และตำแหน่งที่ใช้สรุปข้อมูล</p></div>`,`<button class="primary" data-action="close">กลับไปทำงาน</button>`)}});
$('#prev').onclick=()=>setView(views[(views.indexOf(view)+2)%3]);$('#next').onclick=()=>setView(views[(views.indexOf(view)+1)%3]);document.addEventListener('keydown',e=>{if($('#modal').open||e.target.closest('input,textarea,select,[contenteditable]'))return;if(e.key==='ArrowRight')$('#next').click();if(e.key==='ArrowLeft')$('#prev').click()});window.addEventListener('popstate',()=>{view=views[Number(new URLSearchParams(location.search).get('variant')||1)-1]||'work';render()});render();
